// NOT MY CODE
float sdf_box( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

//Gradient sampler from https://iquilezles.org/articles/palettes/
vec3 palette(float t) 
{
    const vec3 a = vec3(0.5, 0.5, 0.5);
    const vec3 b = vec3(0.5, 0.5, 0.5);
    const vec3 c = vec3(0.5, 1.0, 0.0);
    const vec3 d = vec3(0.50, 0.20, 0.25);
    return a + b * cos(1.28318 * (c * t + d));
}

//Function to create a 2D rotation matrix
mat2 rotate2D(float angle)
{
    float s = sin(angle);
    float c = cos(angle);
    return mat2(c, -s, s, c);
}
