float ray_march(vec3 ray_origin, vec3 ray_direction) 
{
    float total_distance = 0.0;
    for(int i = 0 ; i < 1000 ; ++i) 
    {
        vec3 query_point = ray_origin + ray_direction * total_distance;

        float distance_to_scene = sdf_scene(query_point);
        if(distance_to_scene < 0.0001) break;
        total_distance += distance_to_scene;

        if(total_distance > 1000.0) break;
    }

    return total_distance;
}


vec3 get_color(vec3 origin, vec3 direction) {
    float t_dist = ray_march(origin, direction);
    vec3 point = origin + direction * t_dist;
    vec3 color = palette(length(point)/15.);
    return color;
}

